import { connection } from 'next/server'

export default async function TimestampPage() {
  // Opt out of static prerendering without using cookies/headers.
  // `connection()` stops prerendering and waits for an incoming request,
  // so the code below runs at request time on every page load.
  await connection()

  const timestamp = new Date().toISOString()

  return (
    <main>
      <h1>Server Timestamp</h1>
      <p>This page rendered on the server at:</p>
      <time dateTime={timestamp}>{timestamp}</time>
    </main>
  )
}

